void PlateEditor::chooseFile(bool saving){chooser=std::make_unique<FileChooser>(saving?"Export PLATE 140 preset":"Import PLATE 140 preset",File::getSpecialLocation(File::userDocumentsDirectory).getChildFile("Plate140.xml"),"*.xml");chooser->launchAsync((saving?FileBrowserComponent::saveMode|FileBrowserComponent::warnAboutOverwriting:FileBrowserComponent::openMode)|FileBrowserComponent::canSelectFiles,[this,saving](const FileChooser&fc){auto f=fc.getResult();if(f==File())return;if(saving){auto tree=p.state.copyState();tree.setProperty("version",1,nullptr);if(auto xml=tree.createXml())xml->writeTo(f);}else if(auto xml=XmlDocument::parse(f)){if(PresetLibrary::validState(ValueTree::fromXml(*xml))){p.restoreState(ValueTree::fromXml(*xml));presets.setSelectedId(0,dontSendNotification);}}});}
