void PlateEditor::mouseDown(const MouseEvent&e){if(!e.mods.isPopupMenu())return;PopupMenu menu;auto names=PlateProcessor::presetNames();for(int i=0;i<names.size();++i)menu.addItem(i+1,names[i]);menu.addSeparator();menu.addItem(101,"Open preset browser...");menu.addItem(102,"Reset");menu.addItem(103,"Export preset...");menu.addItem(104,"Import preset...");menu.showMenuAsync(PopupMenu::Options().withTargetComponent(this),[safe=Component::SafePointer<PlateEditor>(this)](int id){if(!safe)return;if(id>0&&id<=platebank::count)safe->p.loadPreset(id-1);if(id==101)safe->openPresets();if(id==102)safe->reset.triggerClick();if(id==103)safe->chooseFile(true);if(id==104)safe->chooseFile(false);});}

void PlateEditor::updatePresetCaption(){auto name=p.state.state.getProperty("preset_name","Default").toString();browse.setButtonText(name);aButton.setToggleState(!usingB,dontSendNotification);bButton.setToggleState(usingB,dontSendNotification);}
void PlateEditor::openPresets(){if(!presetWindow){presetWindow=std::make_unique<PresetWindow>(p,[safe=Component::SafePointer<PlateEditor>(this)]{if(safe)safe->updatePresetCaption();});auto bounds=getScreenBounds();presetWindow->setTopLeftPosition(bounds.getX()+20,bounds.getY()+35);}presetWindow->refresh();presetWindow->setVisible(true);presetWindow->toFront(true);}
